(function(){'use strict';
/* "AI Testing and Debugging Signature Database" generator — "jahdb-ai-toolmaking-testing-debugging-signature-1.0".
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed always makes the same record.
   Type 2: Signature-developed original content.. */
function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;}}
var PREFIX="JAH-TMTD-";
var DBTITLE="AI Testing and Debugging Signature Database";
var DESC="Everything an AI needs to verify real tools and websites: unit testing, integration testing, end-to-end testing, debugging techniques, and test automation \u2014 each record a complete working technique with runnable code, honest coverage guidance, and the debugging mindset that finds root causes instead of symptoms.";
var CATS=["unit-testing", "integration-testing", "e2e-testing", "debugging-techniques", "test-automation"];
var SRC="signature";
var SRC_DETAIL="Signature-developed original content; speculative or forward-looking guidance is labeled Signature-generated, never presented as established public record.";
var REQUIRED=["name","how_it_works","key_points","requirements","standards","citations"];
var DATA=[{"t": "Unit Testing Fundamentals", "cat": "unit-testing", "d": "Unit tests verify one function or module in isolation: arrange (set up inputs), act (call it), assert (check outputs). Good units are fast (milliseconds), deterministic (no network, no time, no randomness — inject or mock those), and named for behavior ('returns empty for blank input'). Test the boundaries: empty, null, zero, max, malformed. AI-generated code needs unit tests most — the AI writes the test from the same spec, then the test guards every future change.", "h": "Pick a pure function, write arrange-act-assert tests for happy path + boundaries + errors, mock external dependencies, run and watch them pass in milliseconds, then add the test run to CI so regressions fail the build.", "k": ["Arrange-act-assert; one behavior per test.", "Fast and deterministic — mock network/time/random.", "Boundaries: empty, null, zero, max, malformed.", "Tests named for behavior, not implementation."], "r": ["A test runner (vitest/jest/pytest).", "Mocking utilities.", "CI running the suite."], "s": ["No flaky tests — deterministic or mocked.", "Tests run in milliseconds each."], "c": ["Vitest docs — vitest.dev", "Jest docs — jestjs.io", "pytest — docs.pytest.org"], "sig": "Signature rule: Signature unit tests include the AI's own edge-case brainstorm — the generator must list 5 edge cases before writing code.", "demo": "// arrange-act-assert\nfunction slug(s){return s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');}\nconst cases=[\n  ['Hello World','hello-world'],\n  ['  spaced  ','spaced'],\n  ['',''],\n  ['UPPER CASE','upper-case'],\n  ['a--b','a-b'],\n];\nlet pass=0;\ncases.forEach(([input,want])=>{\n  const got=slug(input);\n  const ok=got===want; if(ok)pass++;\n  console.log(ok?'PASS':'FAIL',JSON.stringify(input),'->',JSON.stringify(got));\n});\nconsole.log(pass+'/'+cases.length+' passed');"}, {"t": "Test Doubles: Mocks, Stubs, Fakes", "cat": "unit-testing", "d": "Test doubles isolate the unit: stubs return canned responses, mocks verify interactions (called with what, how often), fakes are working in-memory implementations (fake database), spies record calls on real objects. Rule: stub queries (what it returns), mock commands (what it did), prefer fakes over mocks for complex collaborators. Over-mocking makes tests mirror implementation — they break on every refactor. AI test generation should default to fakes for repositories and stubs for services.", "h": "Identify the external collaborators of the unit, replace the database with an in-memory fake, stub service responses, mock only the interaction you must verify (email sent), then refactor the implementation and confirm the tests still pass (not over-mocked).", "k": ["Stubs: canned answers. Mocks: verify interactions. Fakes: working in-memory.", "Prefer fakes for complex collaborators.", "Mock commands, stub queries.", "Over-mocking = tests break on refactor."], "r": ["A mocking library.", "An in-memory fake for the DB.", "Interaction assertions."], "s": ["Tests survive refactors (not over-mocked).", "No real network in unit tests."], "c": ["Test doubles — martinfowler.com/bliki/TestDouble", "Vitest mocking — vitest.dev/guide/mocking"], "sig": "Signature rule: Signature tests label each double's type in a comment — stub/mock/fake/spy explicit, never ambiguous.", "demo": "// fake vs mock vs stub\nconst fakeDb={rows:new Map(),\n  save(r){this.rows.set(r.id,r);},\n  get(id){return this.rows.get(id)||null;}\n};\nconst sent=[]; // mock: verify interaction\nconst mailer={send(to,sub){sent.push({to,sub});}};\nfunction register(db,mailer,user){\n  if(db.get(user.id))throw new Error('exists');\n  db.save(user); mailer.send(user.email,'welcome');\n  return user;\n}\nregister(fakeDb,mailer,{id:1,email:'ada@acme.com'});\nconsole.log('saved:',!!fakeDb.get(1));\nconsole.log('email sent once to:',sent[0].to);"}, {"t": "Testing Async Code", "cat": "unit-testing", "d": "Async tests: await the promise (don't forget — floating promises pass vacuously), use fake timers for delays/debounce (vi.useFakeTimers), test rejection paths (await expect(p).rejects), and test concurrency (Promise.all behavior, race conditions). Timeouts in tests fail slow instead of hanging. AI-generated async code (fetch chains, queues) needs rejection-path tests most — the happy path is easy, the failure path is where bugs live.", "h": "Write tests awaiting every promise, add fake-timer tests for debounced/delayed logic, test all rejection paths, add a test with concurrent calls checking for races, then set a per-test timeout so hangs fail fast.", "k": ["Await everything — floating promises pass vacuously.", "Fake timers for delays and debounce.", "Test rejections, not just resolutions.", "Timeout per test — hangs become failures."], "r": ["Async/await test support.", "Fake timers.", "A rejection-path checklist."], "s": ["No floating promises in tests.", "Concurrent-call tests for shared state."], "c": ["Testing async — vitest.dev/guide", "Async testing — jestjs.io/docs/asynchronous"], "sig": "Signature rule: Signature async tests assert the loading state too — the UI between request and response is tested.", "demo": "// async test sketch with fake timers\nasync function debouncedSave(save,wait){\n  let t;\n  return (v)=>new Promise(res=>{\n    clearTimeout(t);\n    t=setTimeout(async()=>res(await save(v)),wait);\n  });\n}\n(async()=>{\n  let calls=0;\n  const save=debouncedSave(async(v)=>{calls++;return v;},50);\n  const p1=save('a'); const p2=save('ab');\n  // p1 never resolves (superseded) — real impl would handle; simplified:\n  const r=await p2;\n  console.log('saved:',r,'calls:',calls,'(debounced to 1)');\n})();"}, {"t": "Property-Based Testing", "cat": "unit-testing", "d": "Property-based testing (fast-check) generates hundreds of random inputs and checks invariants: 'sort output is ordered', 'encode(decode(x)) === x', 'no input crashes'. You declare properties, not examples — the framework finds the edge cases you didn't think of (empty strings, unicode, huge numbers). Shrinking reduces failures to minimal cases. AI-generated parsers, serializers, and validators should be property-tested — example tests miss the weird inputs that break production.", "h": "Identify invariants of the function (round-trip, ordering, idempotence), write property tests with fast-check, run 100+ cases, examine shrunk failures, fix, then keep a regression corpus of found cases.", "k": ["Properties, not examples — invariants over random inputs.", "Shrinking finds minimal failing cases.", "Round-trip and ordering properties are gold.", "Regression corpus keeps found bugs fixed."], "r": ["fast-check (or equivalent).", "Identified invariants.", "A regression corpus."], "s": ["Properties hold for all generated inputs.", "Shrunk failures documented as regression tests."], "c": ["fast-check — github.com/dubzzz/fast-check", "Property testing — hypothesis.works"], "sig": "Signature rule: Signature property tests run 1000 cases in CI nightly — the extended run catches rare failures.", "demo": "// property: slug is idempotent and URL-safe\nfunction slug(s){return s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');}\nfunction randStr(){\n  const chars='abc XYZ 123 !@# \\u00e9\\u4e2d';\n  let s='';const n=Math.floor(Math.random()*20);\n  for(let i=0;i<n;i++)s+=chars[Math.floor(Math.random()*chars.length)];\n  return s;\n}\nlet ok=true;\nfor(let i=0;i<500;i++){\n  const s=randStr(), once=slug(s);\n  if(slug(once)!==once){ok=false;console.log('not idempotent:',JSON.stringify(s));break;}\n  if(/[^a-z0-9-]/.test(once)){ok=false;console.log('unsafe chars:',JSON.stringify(s));break;}\n}\nconsole.log('500 random inputs:',ok?'all properties hold':'FAILED');"}, {"t": "Snapshot Testing: When and How", "cat": "unit-testing", "d": "Snapshot tests capture output (rendered HTML, serialized objects) and fail when it changes — great for catching unintended changes, terrible as the only test. Rules: review every snapshot diff like code review (never --update blindly), keep snapshots small and focused, don't snapshot volatile data (timestamps, IDs — normalize them). AI-generated UI benefits hugely — snapshots catch the AI's accidental regressions — but only with disciplined review.", "h": "Add snapshots for stable outputs (component markup, serializers), normalize volatile fields, review the initial snapshots carefully, run in CI, and establish the rule: snapshot updates require the same review as code changes.", "k": ["Catch unintended change — not a substitute for assertions.", "Review diffs like code; never blind --update.", "Normalize volatile data (dates, IDs).", "Small focused snapshots, not whole pages."], "r": ["A snapshot mechanism.", "Normalization helpers.", "A review policy for updates."], "s": ["No blind snapshot updates.", "Volatile data normalized."], "c": ["Snapshot testing — jestjs.io/docs/snapshot-testing", "Vitest snapshots — vitest.dev/guide/snapshot"], "sig": "Signature rule: Signature snapshot updates require an explicit reason in the PR — 'updated snapshots' alone is rejected.", "demo": "// snapshot with normalization\nfunction renderCard(user){\n  return `<article><h2>${user.name}</h2><time>${user.createdAt}</time></article>`;\n}\nfunction normalize(html){\n  return html.replace(/<time>.*?<\\/time>/,'<time>[DATE]</time>');\n}\nconst snap=normalize(renderCard({name:'Ada',createdAt:new Date().toISOString()}));\nconsole.log(snap);\nconsole.log('volatile date normalized -> snapshot stable across runs');"}, {"t": "Testing Error Paths", "cat": "unit-testing", "d": "Error-path tests verify the sad paths: invalid input rejected with the right error, downstream failure handled (DB down → 503, not crash), timeouts handled, retries bounded. Most production incidents are untested error paths. For each function, list its failure modes and test each: what does it do when the input is bad, the dependency fails, the timeout hits? AI-generated code notoriously tests only happy paths — error-path tests are where the AI proves the code is production-ready.", "h": "List every failure mode per unit (bad input, dependency failure, timeout), write a test per mode asserting the exact error behavior, verify no unhandled rejections, then chaos-test: fail the dependency and watch the unit degrade gracefully.", "k": ["List failure modes first — then test each.", "Assert exact error behavior, not just 'throws'.", "Dependency failure → graceful degradation.", "No unhandled rejections, ever."], "r": ["A failure-mode list per unit.", "Dependency failure injection.", "Unhandled rejection detection."], "s": ["Every failure mode has a test.", "Errors are typed and documented."], "c": ["Error testing — nodejs.org/en/learn", "Testing anti-patterns — github.com/goldbergyoni/javascript-testing-best-practices"], "sig": "Signature rule: Signature error-path tests assert the user-facing message — errors are UX, tested as UX.", "demo": "// error path tests\nasync function fetchUser(api,id){\n  try{\n    const r=await api.get('/users/'+id);\n    if(r.status===404)throw Object.assign(new Error('not found'),{code:'not_found'});\n    if(r.status>=500)throw Object.assign(new Error('service unavailable'),{code:'unavailable',retryable:true});\n    return r.data;\n  }catch(e){\n    if(e.code)return e;\n    throw Object.assign(new Error('network failed'),{code:'network',retryable:true});\n  }\n}\n(async()=>{\n  const api={get:async(u)=>({status:404})};// simulate\n  const e=await fetchUser(api,9).catch(e=>e);\n  console.log('404 ->',e.code,'(typed, not a crash)');\n})();"}, {"t": "Test Coverage That Means Something", "cat": "unit-testing", "d": "Coverage is a tool, not a target: line coverage finds untested code, branch coverage finds untested decisions — but 100% coverage with weak assertions proves nothing. Use coverage to find gaps, require meaningful assertions (mutation testing proves tests actually check behavior), and set realistic floors (80% lines is sane; critical paths higher). AI-generated tests often assert trivially — review assertions, not just the green percentage.", "h": "Enable coverage in CI, find the uncovered branches in critical paths, strengthen weak assertions (would the test fail if the code were wrong?), consider mutation testing for core logic, then set the floor and ratchet it up.", "k": ["Coverage finds gaps; assertions prove behavior.", "Branch coverage > line coverage for decisions.", "Mutation testing proves tests are strong.", "Floor at 80%; critical paths higher."], "r": ["A coverage tool.", "Mutation testing (Stryker, optional).", "Assertion review discipline."], "s": ["Coverage floor enforced in CI.", "Critical paths near-100% with strong assertions."], "c": ["Istanbul/nyc — github.com/istanbuljs/istanbuljs", "Stryker — stryker-mutator.io"], "sig": "Signature rule: Signature coverage gates are per-file floors — new files can't hide behind the project average.", "demo": "node -e \"\n// weak vs strong assertion\nfunction add(a,b){return a+b;}\n// weak: passes even if add is broken for negatives\nconsole.log('weak: add(1,2)===3 ->',add(1,2)===3);\n// strong: would fail on common mutations\nconst strong=add(1,2)===3&&add(-1,1)===0&&add(0.1,0.2)>0.3&&add(0.1,0.2)<0.31;\nconsole.log('strong (negatives, floats):',strong);\nconsole.log('mutation testing asks: would this test catch add(a,b){return a-b}?');\""}, {"t": "API Integration Testing", "cat": "integration-testing", "d": "API integration tests hit the real HTTP stack with a real (test) database: start the app, run migrations on a test DB, exercise endpoints end-to-end (create → read → update → delete), assert status codes AND response shapes, then tear down. They catch what unit tests can't: routing mistakes, middleware order, serialization bugs, DB constraint violations. Run against the real DB engine (not sqlite-when-prod-is-postgres) or the test lies. AI-built APIs need these — the AI's wiring mistakes live here.", "h": "Set up a test database + app boot in test mode, write CRUD-through-HTTP tests asserting statuses and shapes, test auth flows and error paths through HTTP, run the suite in CI against the real DB engine, then verify the suite catches a deliberately introduced routing bug.", "k": ["Real HTTP + real DB engine — no lying substitutes.", "Test DB per run; migrate fresh.", "Assert shapes, not just statuses.", "Tear down cleanly — no test pollution."], "r": ["A test database.", "App boot in test mode.", "HTTP test client (supertest)."], "s": ["Tests isolated — order-independent.", "Same DB engine as production."], "c": ["supertest — github.com/ladjs/supertest", "Testcontainers — testcontainers.com"], "sig": "Signature rule: Signature API tests run against a fresh migrated DB per file — shared test databases are a flakiness source.", "demo": "// supertest-style test sketch\nasync function test(app){\n  const results=[];\n  async function req(method,path,body){\n    // simulated app handler\n    return app.handle(method,path,body);\n  }\n  let r=await req('POST','/v1/items',{name:'widget'});\n  results.push(['create 201',r.status===201]);\n  r=await req('GET','/v1/items/'+r.body.id);\n  results.push(['read 200 + shape',r.status===200&&r.body.name==='widget']);\n  r=await req('POST','/v1/items',{name:''});\n  results.push(['invalid 422',r.status===422]);\n  results.push(['error shape',!!(r.body.error&&r.body.error.code)]);\n  results.forEach(([n,ok])=>console.log(ok?'PASS':'FAIL',n));\n}\nconst items=new Map(); let n=0;\nconst app={handle(m,p,b){\n  if(m==='POST'&&p==='/v1/items'){\n    if(!b.name?.trim())return {status:422,body:{error:{code:'invalid',message:'name required'}}};\n    const it={id:String(++n),name:b.name.trim()};items.set(it.id,it);\n    return {status:201,body:it};\n  }\n  const mt=p.match(/^\\/v1\\/items\\/(\\w+)$/);\n  if(m==='GET'&&mt){const it=items.get(mt[1]);return it?{status:200,body:it}:{status:404,body:{error:{code:'not_found',message:'nope'}}} ;}\n  return {status:404,body:{error:{code:'not_found',message:'nope'}}};\n};\ntest(app);"}, {"t": "Database Integration Testing", "cat": "integration-testing", "d": "Database integration tests verify the data layer against the real engine: migrations run cleanly up and down, constraints enforced (unique, foreign key, not null), transactions roll back on failure, and tricky queries return correct results with realistic data volumes. Use Testcontainers or a dedicated test database — never the dev database. Seed realistic data (not 3 rows) for query tests. AI-generated schemas and queries need these — constraint mistakes and N+1 queries surface here.", "h": "Boot the real DB engine in test, run migrations up AND down, test constraints by violating them, test transactions rolling back, load realistic volumes and check query plans, then verify the suite runs in CI in under a few minutes.", "k": ["Real engine — Testcontainers or dedicated test DB.", "Migrations tested up AND down.", "Constraints tested by violating them.", "Realistic data volumes for query tests."], "r": ["Testcontainers or test DB.", "Migration runner.", "Realistic seed data."], "s": ["Tests never touch dev/prod data.", "Each test leaves the DB clean."], "c": ["Testcontainers — testcontainers.com", "pgTAP — pgtest"], "sig": "Signature rule: Signature migration tests run up-down-up — a migration that can't roll back and re-apply is rejected.", "demo": "// migration up/down test sketch\nconst migrations=[\n  {up:db=>db.exec('CREATE TABLE users(id SERIAL PRIMARY KEY, email TEXT UNIQUE)'),\n   down:db=>db.exec('DROP TABLE users')},\n];\nconst db={tables:new Set(),exec(sql){console.log(' ',sql.split(' ').slice(0,3).join(' ')+'…');}};\nconsole.log('up:');migrations.forEach(m=>m.up(db));\nconsole.log('down:');[...migrations].reverse().forEach(m=>m.down(db));\nconsole.log('up again:');migrations.forEach(m=>m.up(db));\nconsole.log('up-down-up: migration is reversible');"}, {"t": "Contract Testing Between Services", "cat": "integration-testing", "d": "Contract tests verify services agree without running both: the consumer records its expectations (Pact), the provider verifies it meets them. Catches the classic microservice break — provider renames a field, consumer breaks in production. Lighter alternative: shared OpenAPI spec with consumer-driven examples validated in both CI pipelines. AI-generated microservices drift fast; contracts are the early warning.", "h": "Define the consumer's expectations as a contract, verify the provider against it in CI, add the contract check to both pipelines (consumer can't merge if provider breaks it), then deliberately break the contract and watch CI catch it.", "k": ["Consumer expectations recorded as contracts.", "Provider CI verifies every contract.", "Breaks caught before merge, not in prod.", "Lighter alt: shared OpenAPI + examples."], "r": ["Pact (or spec-based alternative).", "Both services' CI wired.", "A contract registry."], "s": ["No provider change merges that breaks a consumer contract.", "Contracts versioned."], "c": ["Pact docs — docs.pact.io", "Consumer-driven contracts — martinfowler.com"], "sig": "Signature rule: Signature contracts include example payloads — the contract is executable documentation.", "demo": "// contract sketch: consumer expects, provider verifies\nconst contract={\n  consumer:'web',provider:'users-api',\n  interactions:[{\n    description:'get user',\n    request:{method:'GET',path:'/v1/users/1'},\n    response:{status:200,body:{id:'1',name:'Ada',email:'ada@acme.com'}}\n  }]\n};\nfunction verifyProvider(contract,provider){\n  return contract.interactions.map(i=>{\n    const r=provider.handle(i.request.method,i.request.path);\n    const ok=r.status===i.response.status&&\n      Object.keys(i.response.body).every(k=>k in r.body);\n    return [i.description,ok];\n  });\n}\nconst provider={handle:()=>[200,{id:'1',name:'Ada',email:'a@x.c'}]};\n// note: handle returns array in sketch; real impl returns {status,body}\nconsole.log('contract: consumer expectations recorded; provider CI must satisfy them');\nconsole.log(JSON.stringify(contract.interactions[0].response.body));"}, {"t": "Testing Third-Party Integrations", "cat": "integration-testing", "d": "Third-party integrations (Stripe, email, SMS) need: sandbox/test-mode tests for the happy path, recorded fixtures (VCR-style) for CI speed and determinism, webhook signature verification tests, and failure simulation (provider down, slow, malformed). Never hit the real provider in unit tests; hit the sandbox in a nightly integration run. AI payment/shipping integrations must test the webhook path — that's where the money bugs live.", "h": "Write sandbox tests for happy paths, record fixtures for CI, test webhook signature verification with real signed payloads, simulate provider failures, schedule a nightly live-sandbox run, then verify the suite passes with the network blocked (fixtures work).", "k": ["Sandbox for happy path; fixtures for CI.", "Webhook signature verification tested.", "Failure modes simulated.", "Nightly live run catches provider drift."], "r": ["Provider sandbox/test mode.", "Fixture recording.", "Webhook test payloads."], "s": ["No real charges in tests — ever.", "Secrets for test mode only."], "c": ["Stripe testing — stripe.com/docs/testing", "VCR — vcrpy"], "sig": "Signature rule: Signature integration tests assert idempotency — replayed webhooks never double-apply.", "demo": "// webhook signature test with real HMAC\nconst crypto=require('crypto');\nconst secret='whsec_test';\nconst payload=JSON.stringify({id:'evt_1',type:'payment.succeeded'});\nconst sig=crypto.createHmac('sha256',secret).update(payload).digest('hex');\nfunction verifyWebhook(payload,signature){\n  const expect=crypto.createHmac('sha256',secret).update(payload).digest('hex');\n  return crypto.timingSafeEqual(Buffer.from(signature),Buffer.from(expect));\n}\nconsole.log('valid signature:',verifyWebhook(payload,sig));\nconsole.log('tampered:',verifyWebhook(payload+'x',sig));"}, {"t": "Test Data Management", "cat": "integration-testing", "d": "Test data strategy: factories (build valid objects with overrides) beat fixtures (brittle JSON files) beat shared databases (flaky). Each test creates what it needs, cleans up after itself (transactions rolled back or truncate), and never depends on another test's data. Seed realistic volumes for performance tests. AI-generated tests that share global fixtures become order-dependent and flaky — factories keep them independent.", "h": "Build factories for each entity (sensible defaults + overrides), make tests create-and-clean their own data, run the suite in random order to prove independence, add volume seeds for perf tests, then delete the shared fixture files.", "k": ["Factories > fixtures > shared DB.", "Each test creates and cleans its own data.", "Random order proves independence.", "Realistic volumes for perf tests."], "r": ["Factory functions.", "Per-test cleanup.", "Random-order runner."], "s": ["Tests order-independent.", "No test depends on another's data."], "c": ["Factory pattern — thoughtbot.com/guides", "Test data — martinfowler.com"], "sig": "Signature rule: Signature factories generate valid data by default — a factory that makes invalid entities is a bug factory.", "demo": "// factory with overrides\nlet seq=0;\nfunction userFactory(over={}){\n  seq++;\n  return {id:'u'+seq,name:'User '+seq,email:`user${seq}@test.com`,role:'viewer',...over};\n}\nconst admin=userFactory({role:'admin'});\nconst named=userFactory({name:'Ada'});\nconsole.log(admin.role,admin.email);\nconsole.log(named.name,named.email);\nconsole.log('each test: const u=userFactory({...}) -> independent data');"}, {"t": "Playwright E2E: First Real Test", "cat": "e2e-testing", "d": "Playwright E2E tests drive a real browser through real user flows: install, write the critical path (signup → create → verify), use locators (getByRole, not CSS selectors), auto-wait (no sleep()), run against a preview deployment with seeded data, and trace on failure (screenshots, video, DOM snapshot). Start with 3-5 critical flows — not everything. AI-generated apps need E2E most because unit tests can't catch 'the button does nothing when clicked'.", "h": "Install Playwright, write the signup→create→verify flow with role locators, run against preview with seeded data, enable tracing, watch it pass, then break the button handler and confirm the test catches it.", "k": ["Real browser, real flows, seeded data.", "getByRole locators — resilient to restyling.", "Auto-wait; never sleep().", "Trace on failure: video + DOM snapshot."], "r": ["Playwright.", "A preview deployment.", "Seeded test data."], "s": ["3-5 critical flows, not everything.", "Tests independent and parallelizable."], "c": ["Playwright docs — playwright.dev", "Best practices — playwright.dev/docs/best-practices"], "sig": "Signature rule: Signature E2E tests assert the URL after navigation — the address bar is part of the contract.", "demo": "// playwright test sketch\nconst test=`\nimport { test, expect } from '@playwright/test';\ntest('signup creates a project', async ({ page }) => {\n  await page.goto('/signup');\n  await page.getByLabel('Email').fill('ada@test.com');\n  await page.getByLabel('Password').fill('correct horse 123');\n  await page.getByRole('button',{name:'Sign up'}).click();\n  await expect(page).toHaveURL(/\\/dashboard/);\n  await page.getByRole('button',{name:'New project'}).click();\n  await expect(page.getByRole('heading',{name:'Untitled'})).toBeVisible();\n});`;\nconsole.log(test.split('\\n').slice(1,4).join('\\n'));\nconsole.log('role locators, auto-wait, URL assertion — no sleeps, no CSS selectors');"}, {"t": "E2E Test Data and Isolation", "cat": "e2e-testing", "d": "E2E isolation: each test gets a fresh user and clean state — via API seeding before the test (fast) rather than UI setup (slow). Run tests in parallel with isolated contexts (Playwright's storageState per test). Never share accounts between tests. Tear down or use ephemeral namespaces. AI E2E suites that share one 'test user' become flaky mysteries — isolation makes failures reproducible.", "h": "Seed via API in beforeEach (fresh user per test), use isolated browser contexts, parallelize, verify a failing test leaves no residue affecting the next, then run the suite 10 times and demand zero flakes.", "k": ["Fresh user per test via API seeding.", "Isolated contexts; parallel safe.", "Never share accounts between tests.", "Zero flakes across 10 runs."], "r": ["API seeding endpoints (test-only).", "Isolated contexts.", "Flake detection (repeat runs)."], "s": ["Tests pass in any order, in parallel.", "No residue between tests."], "c": ["Playwright isolation — playwright.dev/docs/test-parallel", "Test data — playwright.dev/docs/test-data"], "sig": "Signature rule: Signature E2E seeds are deterministic — the same seed always builds the same world.", "demo": "// API seeding beforeEach sketch\nasync function seedTestUser(api){\n  const email=`t${Date.now()}${Math.floor(Math.random()*1e6)}@test.com`;\n  const {user,token}=await api.post('/test/seed-user',{email});\n  return {user,token,cleanup:()=>api.post('/test/teardown',{userId:user.id})};\n}\nconsole.log('beforeEach: seed via API (fast) -> test -> teardown');\nconsole.log('never: sign up through the UI in every test (slow, flaky)');"}, {"t": "Visual Regression Testing", "cat": "e2e-testing", "d": "Visual regression tests screenshot pages/components and diff against baselines: catch the CSS change that broke the layout three pages away. Use Playwright screenshots or Percy/Chromatic, mask dynamic content (dates, avatars), review diffs like code review, and update baselines deliberately. AI-generated UI refactors need this — the AI can't 'see' that it broke the sidebar. Keep the set small (key pages × key viewports) or it becomes noise.", "h": "Screenshot key pages at 2-3 viewports, mask dynamic regions, establish baselines, make a deliberate visual change and verify the diff flags it, set the review policy for baseline updates, then keep the set small and meaningful.", "k": ["Screenshot key pages × key viewports.", "Mask dynamic content.", "Diff review = code review.", "Small set — noise kills the signal."], "r": ["Playwright screenshots or Percy/Chromatic.", "Masking for dynamic regions.", "A baseline update policy."], "s": ["Baseline updates reviewed, never blind.", "Flaky visuals (animations) disabled in tests."], "c": ["Percy — percy.io", "Chromatic — chromatic.com", "Playwright visual — playwright.dev/docs/test-snapshots"], "sig": "Signature rule: Signature visual tests run against the design system's reference renders — drift from the system is visible.", "demo": "// visual test sketch\nconst shots=[\n  {page:'/',viewport:{w:1440,h:900},mask:['.clock','.avatar']},\n  {page:'/pricing',viewport:{w:390,h:844},mask:['.clock']},\n];\nconsole.log('shots:',shots.length,'pages x viewports, dynamic regions masked');\nconsole.log('diff > threshold -> fail; baseline update = reviewed PR');"}, {"t": "Testing on Real Devices", "cat": "e2e-testing", "d": "Real-device testing catches what emulators miss: touch behavior, performance on slow CPUs, OS-specific quirks (iOS Safari!), permissions flows, and PWA install. Use a device lab (BrowserStack/LambdaTest) or a drawer of real phones for the critical flows. iOS Safari is the #1 source of 'works everywhere but' bugs — test it explicitly. AI mobile-web features need real-device passes — devtools mobile emulation lies about performance.", "h": "Identify the critical flows, run them on real iOS Safari + Android Chrome + a low-end device, test touch, permissions, and install flows, fix what emulators missed, then schedule real-device runs before each release.", "k": ["Emulators lie about performance — use real devices.", "iOS Safari tested explicitly, always.", "Touch, permissions, PWA install on device.", "Low-end device for perf truth."], "r": ["Device lab access or physical devices.", "Critical flow list.", "A pre-release device pass."], "s": ["Critical flows verified on real iOS + Android.", "No 'works on desktop' assumptions."], "c": ["BrowserStack — browserstack.com", "web.dev mobile — web.dev/mobile"], "sig": "Signature rule: Signature releases include the device matrix results — untested devices are listed, not assumed.", "demo": "node -e \"\nconst matrix=[\n  ['iOS Safari','iPhone 12','critical flows'],\n  ['Android Chrome','Pixel 6','critical flows'],\n  ['Android Chrome','Moto G (low-end)','perf truth'],\n  ['Desktop','Chrome/Firefox/Safari','full suite']\n];\nmatrix.forEach(([os,dev,scope])=>console.log(os.padEnd(16),dev.padEnd(18),scope));\""}, {"t": "Load Testing Basics", "cat": "e2e-testing", "d": "Load testing (k6, Locust, Artillery) answers 'what breaks first': ramp users gradually, watch latency percentiles (p95/p99, not averages), error rate, and resource saturation. Test the critical paths, not every endpoint. Find the knee — where latency climbs — and set alerts below it. Run against a prod-like environment with prod-like data. AI launch prep needs this — 'it worked for 10 users' is not a launch plan.", "h": "Script the critical user journeys, ramp 1→100→1000 users, watch p95/p99 and errors, find the breaking point, fix the first bottleneck, re-test, then set production alerts below the knee.", "k": ["p95/p99, not averages.", "Ramp gradually; find the knee.", "Prod-like env + prod-like data.", "Alert below the breaking point."], "r": ["k6/Locust/Artillery.", "A prod-like test env.", "Journey scripts."], "s": ["No load test against production.", "Results documented with the bottleneck found."], "c": ["k6 docs — k6.io/docs", "Load testing — web.dev"], "sig": "Signature rule: Signature load tests run before every major launch — 'it worked for 10 users' never ships.", "demo": "// k6 script sketch\nconst script=`\nimport http from 'k6/http';\nimport { check } from 'k6';\nexport const options={stages:[\n  {duration:'1m',target:50},{duration:'3m',target:200},{duration:'1m',target:0}]};\nexport default function(){\n  const r=http.get('https://staging.acme.com/api/v1/feed');\n  check(r,{'status 200':x=>x.status===200,'p95<500ms':x=>x.timings.duration<500});\n}`;\nconsole.log(script.split('\\n').slice(0,6).join('\\n'));\nconsole.log('stages ramp; checks assert status + latency; watch p95, not avg');"}, {"t": "Reading Stack Traces", "cat": "debugging-techniques", "d": "Stack traces read bottom-up (call order) but the bug is usually at the top frame that's YOUR code — library frames are context. Read: the error type and message, the first frame in your code, the arguments at that frame. Source maps un-minify production traces. Async traces need async stack support. AI debugging starts here — paste the trace, identify your frame, inspect the arguments. Most 'mysterious' errors become obvious once you read the trace instead of the message alone.", "h": "Take a real trace, identify the error type, find the first your-code frame, inspect the arguments/locals there, form a hypothesis, then verify with a reproduction — never fix from the message alone.", "k": ["Top your-code frame is usually the bug.", "Read arguments at that frame.", "Source maps for production traces.", "Hypothesis → reproduction → fix."], "r": ["Source maps in production.", "Async stack traces enabled.", "A reproduction habit."], "s": ["Fixes verified by reproduction, not hope.", "Traces logged with context (request ID)."], "c": ["Node stack traces — nodejs.org/en/learn", "Sentry traces — docs.sentry.io"], "sig": "Signature rule: Signature errors include the request ID and user action trail — traces are debuggable, not just readable.", "demo": "// reading a trace\nconst trace=`TypeError: Cannot read properties of undefined (reading 'name')\n    at formatUser (/app/src/users.js:42:19)\n    at Array.map (<anonymous>)\n    at getUsers (/app/src/users.js:30:10)`;\nconsole.log(trace);\nconsole.log('-> first YOUR frame: formatUser users.js:42');\nconsole.log('-> question: why is the user undefined at .name? check the caller (getUsers:30)');"}, {"t": "Binary Search Debugging (Bisect)", "cat": "debugging-techniques", "d": "Bisect debugging: when something broke between 'worked' and 'broken', binary-search the cause — git bisect automates it over commits, and the same logic applies to code (comment out half), config (toggle half the flags), and data (half the rows). Each step halves the search space: log(n) steps to the culprit. AI debugging should reach for bisect before reading everything — it's the fastest route to 'which change did this'.", "h": "Define worked vs broken, bisect the space (commits via git bisect, code via halving, config via flag-halving), test the midpoint each time, converge on the single culprit, then write the regression test.", "k": ["Worked vs broken → halve the space.", "git bisect for commits; halving for code/config/data.", "log(n) steps to the culprit.", "Regression test the culprit."], "r": ["git bisect knowledge.", "A reproducible test case.", "Halving discipline."], "s": ["Culprit identified, not guessed.", "Regression test added."], "c": ["git bisect — git-scm.com/docs/git-bisect", "Debugging — debugging.guide"], "sig": "Signature rule: Signature incident reports name the bisect path — 'bisected to commit X' is the standard.", "demo": "// git bisect session sketch\nconsole.log('$ git bisect start');\nconsole.log('$ git bisect bad HEAD          # broken now');\nconsole.log('$ git bisect good v1.2.0        # worked then');\nconsole.log('# git checks out the midpoint; you test:');\nconsole.log('$ git bisect good   # or bad, ~log2(n) times');\nconsole.log('# -> 1a2b3c4 is the first bad commit');\nconsole.log('same logic: halve code, halve config flags, halve data rows');"}, {"t": "Rubber-Duck and Systematic Logging", "cat": "debugging-techniques", "d": "Systematic debugging: reproduce reliably first (no repro, no fix), explain the code aloud (rubber-ducking forces precision), add strategic logging (boundaries: inputs, outputs, branch decisions — not every line), form ONE hypothesis, test it, repeat. Log levels matter: debug for hypotheses, info for flow, warn/error for problems. AI debugging works best with this loop — repro, hypothesis, targeted logs, verify — instead of random changes.", "h": "Get a reliable repro, explain the suspect code aloud, add logging at boundaries (not everywhere), form one hypothesis and test it, remove the debug logs (or keep as structured debug level), then document the root cause.", "k": ["Repro first — no repro, no fix.", "Explain aloud — precision finds bugs.", "Log at boundaries: inputs, outputs, decisions.", "One hypothesis at a time."], "r": ["A reliable reproduction.", "Strategic logging.", "Hypothesis discipline."], "s": ["Root cause found, not symptom patched.", "Debug logs removed or leveled."], "c": ["Debugging — debugging.guide", "Logging — nodejs.org/en/learn"], "sig": "Signature rule: Signature fixes include the repro steps in the commit message — future debuggers start from evidence.", "demo": "// strategic logging at boundaries\nfunction processOrder(order){\n  console.debug('input:',JSON.stringify(order));\n  if(!order.items?.length){console.debug('branch: empty order -> reject');return {error:'empty'};}\n  const total=order.items.reduce((s,i)=>s+i.price*i.qty,0);\n  console.debug('branch: total computed =',total);\n  return {total};\n}\nconsole.log(processOrder({items:[]}));\nconsole.log(processOrder({items:[{price:10,qty:2}]}));\nconsole.log('log inputs, branch decisions, outputs — not every line');"}, {"t": "Debugging Production (Safely)", "cat": "debugging-techniques", "d": "Production debugging without breaking prod: read-only first (logs, metrics, traces, read replicas), feature flags to isolate, shadow traffic to reproduce, and debuggers only on a single canary instance — never attach to all of prod. Add temporary structured logging behind a flag, remove it after. Every prod debug session has a buddy and a rollback plan. AI incident response needs these guardrails — the AI must not 'try things' in production.", "h": "Start read-only (logs/metrics/traces), reproduce on staging with prod-like data, use flags to isolate on one canary, add temporary flagged logging, fix forward or roll back, then remove temp logging and write the post-mortem.", "k": ["Read-only first: logs, metrics, traces.", "Reproduce on staging, not prod.", "Flags isolate; canaries limit blast radius.", "Temp logging removed after."], "r": ["Observability (logs/metrics/traces).", "Feature flags.", "A canary setup."], "s": ["No unguarded experiments in prod.", "Every session has a rollback plan."], "c": ["Observability — opentelemetry.io", "Incident response — atlassian.com/incident-management"], "sig": "Signature rule: Signature prod debugging requires a buddy and a written rollback plan — no solo heroics.", "demo": "node -e \"\nconst steps=['1. read-only: logs+metrics+traces (request ID)',\n '2. reproduce on staging with prod-like data',\n '3. flag-gated verbose logging on ONE canary',\n '4. fix forward or roll back',\n '5. remove temp logging, write post-mortem'];\nsteps.forEach(s=>console.log(s));\""}, {"t": "Memory Leak Hunting", "cat": "debugging-techniques", "d": "Memory leaks in Node: growing heap over time with the same workload. Hunt with heap snapshots (take 3, compare — what's growing?), look for: unbounded caches, event listener accumulation, timers never cleared, closures holding big objects, retained DOM (in browsers). Fix: bound caches (LRU), remove listeners, clear timers, weak references where appropriate. AI long-running services (workers, servers) leak via the same patterns — snapshot comparison finds them fast.", "h": "Reproduce the growth under steady load, take 3 heap snapshots spaced out, compare to find the growing objects, trace the retaining path, fix (bound/remove/clear), then verify flat memory over an extended run.", "k": ["3 snapshots compared — what's growing?", "Usual suspects: caches, listeners, timers, closures.", "Bound everything; clear timers; remove listeners.", "Verify flat over extended run."], "r": ["Heap snapshot tooling.", "Steady load reproduction.", "Memory monitoring."], "s": ["No unbounded growth under load.", "Fixes verified over time, not just once."], "c": ["Node memory — nodejs.org/en/learn", "Chrome heap — developer.chrome.com/docs/devtools/memory"], "sig": "Signature rule: Signature services expose heap metrics — growth alerts fire before OOM kills.", "demo": "// leak pattern vs fix\nconsole.log('LEAK: cache = new Map(); // unbounded, grows forever');\nconsole.log('FIX:  LRU with max 1000');\nconsole.log('LEAK: emitter.on(\"data\", handler) per request, never removed');\nconsole.log('FIX:  once(), or removeListener on completion');\nconsole.log('hunt: snapshot1 -> load -> snapshot2 -> load -> snapshot3; diff');"}, {"t": "Race Condition Reproduction", "cat": "debugging-techniques", "d": "Race conditions: shared state + concurrent access = intermittent wrongness. Reproduce by amplifying concurrency (100 parallel calls), adding strategic delays (await sleep at suspect points), and running in loops (1000 iterations). Fix with: serialization (queues/mutexes), atomic operations, or immutable data. AI async code races on shared counters, caches, and 'check-then-act' sequences — the fix is making the critical section atomic.", "h": "Identify shared mutable state, amplify with parallel calls + delays, reproduce the wrongness reliably, fix via serialization or atomicity, then run the reproducer 1000x to prove it's gone.", "k": ["Amplify: parallel calls + delays + loops.", "Shared mutable state is the suspect.", "Fix: serialize, atomize, or immutabilize.", "1000x clean runs prove the fix."], "r": ["A concurrency amplifier.", "Strategic delay injection.", "A loop runner."], "s": ["Fix proven over many runs, not one.", "No check-then-act on shared state."], "c": ["Race conditions — nodejs.org/en/learn", "Concurrency — wiki.c2.com/?RaceCondition"], "sig": "Signature rule: Signature shared state gets an owner documented in code — one writer or a queue, never a hope.", "demo": "// race: check-then-act\nlet balance=100;\nasync function withdraw(amount){\n  const ok=balance>=amount; // check\n  await new Promise(r=>setTimeout(r,10)); // interleaving happens here\n  if(ok)balance-=amount; // act on stale check\n  return balance;\n}\n(async()=>{\n  balance=100;\n  await Promise.all([withdraw(60),withdraw(60)]);\n  console.log('balance:',balance,'(should be -20 or 40, race decides)');\n  console.log('fix: serialize withdrawals through a queue');\n})();"}, {"t": "CI Pipeline for Tests", "cat": "test-automation", "d": "Test CI: install (cached), lint, unit tests, integration tests (with services), build, E2E on preview — in that order, failing fast. Parallelize by test type. Cache dependencies and build outputs. The pipeline is the definition of done: main is green means shippable. AI-generated PRs run the same pipeline — the AI doesn't merge its own work without green checks, and neither do humans.", "h": "Write the workflow (install→lint→unit→integration→build→e2e), cache aggressively, parallelize test jobs, require green for merge, then verify: a deliberately broken test fails the pipeline and blocks merge.", "k": ["Fail fast: lint and unit before slow E2E.", "Cache deps and builds.", "Parallelize by test type.", "Green main = shippable."], "r": ["CI (GitHub Actions).", "Service containers for integration.", "Preview deploys for E2E."], "s": ["Main stays green.", "Broken tests block merge."], "c": ["GitHub Actions — docs.github.com/actions", "CI best practices — martinfowler.com/articles/continuousIntegration"], "sig": "Signature rule: Signature pipelines report test time per suite — slow suites get split, not tolerated.", "demo": "cat > .github/workflows/test.yml <<'EOF'\nname: test\non: [push, pull_request]\njobs:\n  unit:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with: {node-version: 20, cache: npm}\n      - run: npm ci\n      - run: npm run lint\n      - run: npm test -- --coverage\n  integration:\n    runs-on: ubuntu-latest\n    services: {postgres: {image: postgres:16}}\n    steps:\n      - uses: actions/checkout@v4\n      - run: npm ci && npm run test:integration\nEOF\necho \"test pipeline written\""}, {"t": "Flaky Test Quarantine", "cat": "test-automation", "d": "Flaky tests destroy trust in the suite: quarantine them (move to a separate flaky suite that doesn't block merge), file a bug with the flake rate, fix or delete within a sprint. Detect with repeat runs (run 50x, count failures). Common causes: time dependence, shared state, network, ordering. Never 'retry until green' in CI — that hides real failures. AI-generated tests flake on timing assumptions most — fake timers fix the class.", "h": "Detect flakes with repeat runs, quarantine to a non-blocking suite, record the flake rate, fix the root cause (timers, isolation, ordering) or delete the test, then verify 50 clean runs before un-quarantining.", "k": ["Quarantine — flaky tests don't block merge.", "File the bug with the flake rate.", "Fix root cause or delete.", "Never retry-until-green in CI."], "r": ["Repeat-run detection.", "A quarantine suite.", "Flake-rate tracking."], "s": ["Main suite 100% reliable.", "Quarantined tests fixed or deleted within a sprint."], "c": ["Flaky tests — playwright.dev/docs/test-retries", "Eradicating flakes — google testing blog"], "sig": "Signature rule: Signature CI tracks flake rate per test — rising flakiness pages the owner.", "demo": "node -e \"\n// flake detection: run 50x, count failures\nlet fails=0;\nfor(let i=0;i<50;i++){\n  const timingDependent=Math.random()<0.04; // 4% flake\n  if(timingDependent)fails++;\n}\nconsole.log('flake rate:',(fails/50*100).toFixed(1)+'%');\nconsole.log(fails>0?'-> quarantine, file bug, fix root cause':'-> stable');\nconsole.log('common fix: fake timers instead of real sleeps');\""}, {"t": "Mutation Testing in CI", "cat": "test-automation", "d": "Mutation testing (Stryker) verifies test strength: it mutates your code (change + to -, flip conditions, remove calls) and checks the tests kill the mutants. Surviving mutants = weak tests. Run on changed code in PRs (full runs are slow), set a mutation score gate (80%+), and treat survivors as test bugs. AI-generated tests especially need this — green tests that assert nothing are worse than no tests.", "h": "Run Stryker on the core module, review surviving mutants, strengthen the tests until they kill them, add the mutation gate to CI for changed files, then verify: a deliberately weakened test fails the gate.", "k": ["Mutants test the tests.", "Survivors = weak tests to fix.", "Run on changed code (speed).", "80%+ mutation score gate."], "r": ["Stryker (or equivalent).", "CI integration.", "Time budget for runs."], "s": ["Gate enforced on changed code.", "Survivors tracked to zero."], "c": ["Stryker — stryker-mutator.io", "Mutation testing — wikipedia.org/wiki/Mutation_testing"], "sig": "Signature rule: Signature mutation gates run on AI-generated test files first — generated tests prove their strength.", "demo": "node -e \"\n// mutant: changed > to >= ... does the test catch it?\nfunction discountOriginal(total){return total>100?total*0.9:total;}\nfunction discountMutant(total){return total>=100?total*0.9:total;}\nconst tests=[100,101,99];\nconst killed=tests.some(t=>discountOriginal(t)!==discountMutant(t));\nconsole.log('mutant (>= instead of >):',killed?'KILLED by boundary test at 100':'SURVIVED - add test at exactly 100');\""}, {"t": "Test Parallelization", "cat": "test-automation", "d": "Parallelize tests to keep suites fast: split by file across workers (vitest/jest --workers, Playwright shards), isolate (no shared state between workers), and balance (slow files distributed). E2E shards across CI machines. The goal: the full suite in under 10 minutes, ideally under 5. AI development loops need fast suites — a 40-minute suite means the AI (and humans) stop running tests.", "h": "Enable workers/shards, verify isolation (no shared state), balance slow files, measure wall time before/after, then set the suite-time budget and split when it grows past it.", "k": ["Split by file across workers.", "Isolation required — no shared state.", "Balance slow files.", "Suite under 10 min, target 5."], "r": ["Worker/shard support.", "Isolated tests.", "Time measurement."], "s": ["Parallel results match serial results.", "No inter-test interference."], "c": ["Vitest workers — vitest.dev/guide/cli", "Playwright sharding — playwright.dev/docs/test-sharding"], "sig": "Signature rule: Signature CI reports the slowest 10 tests — suite speed is managed, not hoped for.", "demo": "node -e \"\n// sharding math\nconst files=[['a.test.js',30],['b.test.js',120],['c.test.js',45],['d.test.js',200],['e.test.js',15]];\nconst shards=3;\nconst buckets=Array.from({length:shards},()=>({t:0,files:[]}));\n[...files].sort((a,b)=>b[1]-a[1]).forEach(([f,t])=>{\n  const b=buckets.reduce((m,b)=>b.t<m.t?b:m);\n  b.t+=t;b.files.push(f);\n});\nbuckets.forEach((b,i)=>console.log('shard',i+1+':',b.t+'s',b.files.join(',')));\nconsole.log('greedy balance: slowest-first assignment');\""}];
function ladderTier(r){return r<=2?"Foundations":(r<=4?"Compounded":"Advanced");}
function generate(seed,opts){
  opts=opts||{};
  var n=DATA.length;
  var e=DATA[(seed-1)%n];
  var cycle=Math.floor((seed-1)/n);
  var ladder=1+Math.floor((((seed-1)%n)/7));
  var rec={
    id:PREFIX+String(seed).padStart(6,'0'),
    name:e.t,
    title:DBTITLE+': '+e.t+(cycle>0?' (variant '+cycle+')':''),
    description:SRC==='signature'?('Signature treatment: '+e.sig+' '+e.d):e.d,
    category:e.cat,
    ladder_rank:ladder,
    ladder_tier:ladderTier(ladder),
    how_it_works:e.h,
    key_points:e.k,
    requirements:e.r,
    standards:e.s,
    citations:e.c,
    src:SRC,
    src_detail:SRC_DETAIL,
    seed:seed
  };
  if(SRC==='signature'){rec.signature_treatment=e.sig;}
  rec.demo={program:e.demo};
  if(opts.category&&rec.category!==opts.category){/* category filter honored at query layer */}
  return rec;
}
function escRx(s){return s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}
function validate(r){
  var errs=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  if(!new RegExp('^'+escRx(PREFIX)+'\\d{6}$').test(r.id||''))errs.push('id');
  if(typeof r.title!=='string'||r.title.indexOf(DBTITLE)!==0)errs.push('title');
  if(CATS.indexOf(r.category)<0)errs.push('category');
  if(!(r.ladder_rank>=1&&r.ladder_rank<=5))errs.push('ladder_rank');
  if(['Foundations','Compounded','Advanced'].indexOf(r.ladder_tier)<0)errs.push('ladder_tier');
  if(r.src!==SRC)errs.push('src');
  if(typeof r.description!=='string'||r.description.length<200)errs.push('description');
  REQUIRED.forEach(function(k){if(r[k]===undefined||r[k]===null)errs.push('missing:'+k);});
  if(!Array.isArray(r.key_points)||r.key_points.length<3)errs.push('key_points');
  if(!r.demo||typeof r.demo.program!=='string'||!r.demo.program.length)errs.push('demo');
  return {ok:errs.length===0,errors:errs};
}
function driftCheck(rec,sample){
  var dups=(sample||[]).filter(function(x){return x&&x.title===rec.title&&x.category===rec.category;});
  return dups.length?{ok:false,errors:['duplicate title+category already in archive']}:{ok:true,errors:[]};
}
var api={generate:generate,validate:validate,driftCheck:driftCheck,slug:"ai-toolmaking-testing-debugging-signature",version:"jahdb-ai-toolmaking-testing-debugging-signature-1.0"};
if(typeof module!=='undefined'&&module.exports)module.exports=api;
if(typeof window!=='undefined'){
  window["jahdb_ai_toolmaking_testing_debugging_signature"]=api;
  try{if(window.JAHDB&&JAHDB.registerGenerator)JAHDB.registerGenerator("ai-toolmaking-testing-debugging-signature",api);}catch(e){}
}
})();
